import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';

export async function run({ page, name }: { page: Page; name: string }): Promise<{ name: string; status: string }> {
  await page.setContent(
    `<button>Continue ${name}</button><div role="status">idle</div><script>document.querySelector('button').addEventListener('click',()=>{document.querySelector('[role="status"]').textContent='done-${name}';});</script>`
  );
  await page.getByRole('button', { name: `Continue ${name}` }).click();
  await expect(page.getByRole('status')).toHaveText(`done-${name}`);
  const raw = await page.getByRole('status').textContent();
  const status = (raw ?? '').trim();
  return { name, status };
}
